  \draw[red!75!black,dashed,->] (0,0) -- (1.25,0) node[right] {$+\infty$};
  \draw[very thick,blue!75!black] (-0.5,-0.5) -- (0.5,-0.5) -- (0.5,0.5) -- (-0.5,0.5) -- cycle;
